export const $=s=>document.querySelector(s);
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let worldQuery='';
let route='home',cleanup=null,filter='all',boardGame='bugs',boardDiff=3,boardLearn=false,boardMode='solo',boardPeriod='all',personal=false,achievementQueue=[];
let appUpdater=null;
const updates=createUpdateUI({games:GAMES,artwork,notify,onBack:()=>navigate('home'),beforeEntry:()=>{cleanup?.();cleanup=null;endInstructionSession();}});
function selectGameSession(game){selectInstructionSession(game);updates.setGame(game);}
export function notify(message,kind='info'){let n=document.createElement('div');n.className='notification '+kind;n.textContent=message;$('#notifications').append(n);setTimeout(()=>n.remove(),kind==='achievement'?6500:4200);}
export function modal(content,setup){let d=$('#modal');if(d.open)d.close();d.innerHTML=`<button class="modal-close icon-btn" aria-label="Close dialog">✕</button>${content}`;d.querySelector('.modal-close').onclick=()=>d.close();const title=d.querySelector('h1,h2,h3');if(title){if(!title.id)title.id='modalTitle';d.setAttribute('aria-labelledby',title.id);}else{d.removeAttribute('aria-labelledby');d.setAttribute('aria-label','Arcade dialog');}d.showModal();setup?.(d);return d;}
export function ask(title,message){return new Promise(resolve=>{let d=document.createElement('dialog');d.className='modal confirm-dialog';d.setAttribute('aria-label',title);d.innerHTML=`<div class="eyebrow">ONE QUICK CHECK</div><h2>${esc(title)}</h2><p>${esc(message)}</p><div class="modal-actions"><button class="btn secondary" data-no>Keep it</button><button class="btn danger" data-yes>Yes, continue</button></div>`;document.body.append(d);let done=v=>{d.close();d.remove();resolve(v);};d.querySelector('[data-no]').onclick=()=>done(false);d.querySelector('[data-yes]').onclick=()=>done(true);d.oncancel=e=>{e.preventDefault();done(false);};d.showModal();});}
export async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{notify('Fullscreen is unavailable here. On Windows, F11 also works.');}}
export function setImmersive(v){document.body.classList.toggle('immersive',v);}
function playerChip(){let p=player();document.body.classList.toggle('theme-aurora',p?.theme==='aurora');document.body.classList.toggle('theme-nebula',p?.theme==='nebula');$('#activeProfile').innerHTML=p?`<span class="avatar small ${p.cosmetic==='halo'?'halo':''}" style="--player:${esc(p.color)}">${p.avatar}</span><span>${esc(p.name)}<small>LEVEL ${levelOf(p)}</small></span><b>⌄</b>`:'Choose player';$('#mute').textContent=DB.settings.muted?'♪̸':'♪';$('#mute').setAttribute('aria-pressed',String(DB.settings.muted));$('#mute').setAttribute('aria-label',DB.settings.muted?'Unmute all audio':'Mute all audio');document.body.classList.toggle('reduce-motion',!!DB.settings.reduceMotion);}
function syncFullscreen(){const active=!!document.fullscreenElement;for(const id of ['fullscreen','arenaFull','studioFull','beatFull','refFull']){const b=document.getElementById(id);if(b){b.setAttribute('aria-pressed',String(active));b.setAttribute('aria-label',active?'Exit fullscreen':'Enter fullscreen');}}const b=document.getElementById('fullSettings');if(b)b.textContent=active?'⛶ EXIT FULLSCREEN':'⛶ FULLSCREEN';}document.addEventListener('fullscreenchange',syncFullscreen);$('#activeProfile').onclick=choosePlayer;$('#mute').onclick=()=>{audio();DB.settings.muted=!DB.settings.muted;save();applyAudio();playerChip();};$('#fullscreen').onclick=fullscreen;
document.addEventListener('click',e=>{let b=e.target.closest('[data-nav]');if(b)navigate(b.dataset.nav);let game=e.target.closest('[data-game]');if(game)setupGame(game.dataset.game);if(e.target.closest('button')){audio();if(!e.target.closest('.pad,.step'))fx('tap');}});
window.addEventListener('hashchange',()=>{let r=location.hash.slice(1);if(['home','players','boards','trophies','rivals','settings'].includes(r)&&r!==route)navigate(r,false);});
bus.addEventListener('change',playerChip);bus.addEventListener('error',e=>notify(e.detail,'error'));bus.addEventListener('achievement',e=>{achievementQueue.push(e.detail);flushAchievement();});let achievementBusy=false;function flushAchievement(){if(achievementBusy||!achievementQueue.length)return;achievementBusy=true;let{profile,badge}=achievementQueue.shift();notify(`${badge.icon} ${profile.name} unlocked ${badge.name}! +${badge.xp} XP`,'achievement');fx('achievement');setTimeout(()=>{achievementBusy=false;flushAchievement();},1800);}
function heading(kicker,title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div>${actions}</div>`;}
export function navigate(next='home',hash=true){$('#modal')?.close();updates.cancel();updates.setGame(null);endInstructionSession();cleanup?.();cleanup=null;setImmersive(false);route=next;if(hash)history.replaceState(null,'','#'+next);document.querySelectorAll('[data-nav]').forEach(b=>{b.classList.toggle('current',b.dataset.nav===next);if(b.dataset.nav===next)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#view').className='view '+next;({home:lobby,players:profiles,boards:boards,trophies:trophies,rivals:rivals,settings:settings}[next]||lobby)();playerChip();syncFullscreen();window.scrollTo(0,0);const title=$('#view h1');if(title){title.tabIndex=-1;title.focus({preventScroll:true});}renderAppUpdate();}
function cosmicArt(){return `<svg viewBox="0 0 660 440" class="cosmic-machine" aria-hidden="true"><defs><radialGradient id="planetGlow"><stop stop-color="#9370fb" stop-opacity=".45"/><stop offset="1" stop-color="#9370fb" stop-opacity="0"/></radialGradient><linearGradient id="cabinet" x2="1" y2="1"><stop stop-color="#8b5ee8"/><stop offset="1" stop-color="#3c3472"/></linearGradient><linearGradient id="screen" x2="0" y2="1"><stop stop-color="#13283d"/><stop offset="1" stop-color="#17213d"/></linearGradient></defs><ellipse cx="360" cy="384" rx="208" ry="27" fill="#030819" opacity=".6"/><circle cx="350" cy="209" r="230" fill="url(#planetGlow)"/><g class="orbit-ring"><ellipse cx="350" cy="200" rx="260" ry="105" fill="none" stroke="#5e548b" stroke-width="1" stroke-dasharray="3 9" transform="rotate(-26 350 200)"/></g><circle cx="128" cy="135" r="35" fill="#332d5b" stroke="#a487e8" stroke-width="2"/><ellipse cx="128" cy="135" rx="58" ry="12" fill="none" stroke="#9d73ee" stroke-width="7" transform="rotate(-23 128 135)"/><g class="floating-machine" transform="translate(228 29) rotate(8 115 190)"><path d="M3 36L230 7l21 60-14 303-223 16-18-61 28-123z" fill="url(#cabinet)" stroke="#b19af3" stroke-width="3"/><path d="M16 42l201-24 16 45-206 25z" fill="#242044"/><text x="126" y="58" fill="#f2eaff" font-size="23" font-family="Outfit,sans-serif" font-weight="900" text-anchor="middle" transform="rotate(-7 126 58)">LITTLE BIG</text><path d="M33 105l186-23-3 144-179 20z" fill="#14192e" stroke="#a68cde" stroke-width="4"/><path d="M46 117l160-20-3 115-153 18z" fill="url(#screen)"/><g fill="#d3b7ff"><path d="M118 137l8 22 24 5-20 15 1 24-19-14-22 8 7-23-14-19 24 1z"/><circle cx="66" cy="139" r="3"/><circle cx="182" cy="121" r="3"/><circle cx="183" cy="194" r="3"/></g><path d="M36 249l179-20 24 48-222 25z" fill="#c19aff" stroke="#e0c9ff" stroke-width="2"/><ellipse cx="84" cy="267" rx="18" ry="7" fill="#6e4fa9"/><path d="M84 266v-24" stroke="#22213d" stroke-width="7"/><circle cx="84" cy="239" r="11" fill="#44dcd4"/><ellipse cx="158" cy="258" rx="13" ry="7" fill="#ff82ad"/><ellipse cx="190" cy="254" rx="13" ry="7" fill="#ffcf5a"/><path d="M25 314l198-22-3 65-185 17z" fill="#3b2f68"/><path d="M103 316l48-5v17l-48 6z" fill="#12182b"/><text x="125" y="352" fill="#b49bda" font-size="10" text-anchor="middle" font-family="Outfit,sans-serif" letter-spacing="4">PLAY FOREVER</text></g><g class="float-star"><path d="M536 95l9 24 24 9-24 10-9 24-9-24-24-10 24-9z" fill="#ffcf59"/><path d="M151 315l6 15 15 6-15 6-6 15-6-15-15-6 15-6z" fill="#45e1d6"/></g><circle cx="554" cy="288" r="39" fill="#352944" stroke="#d6779c" stroke-width="2"/><path d="M524 287q30-20 62 0m-54 17q23-12 46-2" fill="none" stroke="#ad5f83" stroke-width="7"/><circle cx="179" cy="68" r="4" fill="#43e6d1"/><circle cx="600" cy="196" r="5" fill="#a783f7"/><path d="M88 233v15m-7-7h14M467 369v15m-7-7h14" stroke="#a59bca" stroke-width="2"/></svg>`;}
function lobby(){let p=player(),progress=p?levelProgress(p):null;$('#view').innerHTML=`<section class="lobby-hero"><div class="hero-orbit-text">✦ &nbsp; NEON ARCADE UNIVERSE &nbsp; / &nbsp; EST. 2026</div><div class="hero-copy"><div class="welcome"><span class="status-dot"></span> ${p?`WELCOME BACK, ${esc(p.name.toUpperCase())}`:'YOUR ADVENTURE STARTS HERE'}</div><h1>A little play.<br><span>A lot of possibility.</span></h1><p>Find a new favorite. Make something wonderful.<br>Bring a friend. There’s room for everyone.</p><div class="hero-buttons"><button id="quickPlay" class="btn primary"><span>▶</span> SURPRISE ME <b>↗</b></button><button id="heroPlayers" class="btn ghost">${p?.avatar||'☺'} SWITCH PLAYER</button></div><div class="hero-meta"><span>${GAMES.length} WORLDS</span><i>✦</i><span>1–2 PLAYERS</span><i>✦</i><span>MADE FOR YOUR CREW</span></div></div><div class="hero-visual">${cosmicArt()}<div class="hero-character hero-buddy">${artwork('buddy')}</div><div class="hero-character hero-robot">${artwork('robot')}</div><span class="orbit-label">INSERT IMAGINATION<br><b>NO COINS NEEDED</b></span></div></section><section class="player-ribbon"><div class="ribbon-label">WHO’S PLAYING?<small>PICK YOUR PLAYER</small></div><div id="lobbyProfiles">${DB.profiles.slice(0,6).map(q=>`<button class="player-pill ${q.id===DB.active?'selected':''}" data-player="${q.id}" style="--player:${q.color}"><span class="premium-avatar">${iconArt('avatar',q.avatar)}</span><div>${esc(q.name)}<small>LV. ${levelOf(q)}</small></div>${q.id===DB.active?'<i>✓</i>':''}</button>`).join('')}<button class="add-player" id="addProfile" aria-label="Add or select players">＋</button></div>${progress?`<div class="ribbon-xp"><span>LEVEL ${progress.level}<b>${p.xp} XP</b></span><div class="xp-track"><i style="width:${progress.value/progress.max*100}%"></i></div><small>${progress.max-progress.value} XP TO NEXT LEVEL</small></div>`:''}</section><section class="discovery-section"><div class="discovery-heading"><div><div class="eyebrow">A LITTLE INSPIRATION</div><h2>Where will you go today?</h2><p>Three fresh picks, right here each day.</p></div></div><div class="daily-worlds">${dailyWorlds(GAMES).map(g=>`<button class="daily-world" data-game="${g.id}"><span aria-hidden="true">${g.icon}</span><span><strong>${esc(g.name)}</strong><small>${esc(g.tag)}</small></span><b aria-hidden="true">↗</b></button>`).join('')}${recentWorld(GAMES)?`<button class="daily-world" data-game="${recentWorld(GAMES).id}"><span aria-hidden="true">↶</span><span><strong>Back to ${esc(recentWorld(GAMES).name)}</strong><small>Last world opened on this browser</small></span><b aria-hidden="true">↗</b></button>`:''}</div></section><section class="games-section"><div class="section-title"><div><div class="eyebrow">CHOOSE YOUR WORLD</div><h2>The arcade is <em>yours.</em></h2></div><div class="game-filters" role="group" aria-label="Filter worlds">${[['all','All worlds'],['arcade','Arcade'],['learn','Learn & play'],['creative','Create'],['together','Together']].map(([id,label])=>`<button data-filter="${id}" aria-pressed="${filter===id}" class="${filter===id?'active':''}">${label}</button>`).join('')}</div></div><label class="world-search"><span>Find your next adventure</span><input type="search" id="worldSearch" placeholder="Search worlds, art, music…" value="${esc(worldQuery)}" aria-controls="deck" autocomplete="off"></label><p class="world-count" id="worldCount" role="status" aria-live="polite"></p><div class="game-deck" id="deck"></div></section><section class="lobby-extras"><button class="lab-promo" data-game="beat"><span class="eyebrow">TURN UP YOUR IMAGINATION</span><h3>BEAT LAB<span>↗</span></h3><p>16 pads. Infinite possibilities.<br>Your next big beat starts here.</p><div class="mini-pads" aria-hidden="true">${Array.from({length:12},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div></button><button class="gallery-promo" data-game="paint"><span class="eyebrow">A LITTLE MESS. A LOT OF MAGIC.</span><h3>CREATIVE STUDIO<span>↗</span></h3><p>Draw, stamp & remix your world.<br>Every idea belongs on the canvas.</p><span class="studio-squiggle" aria-hidden="true">✿ ✦ ✎</span></button><button class="fame-promo" data-nav="boards"><span class="eyebrow">THE LEGENDS LIVE HERE</span><div class="fame-crown">♛</div><h3>HALL OF FAME ↗</h3><p>Earn your place among<br>the arcade’s all-stars.</p></button></section><div class="bottom-message"><span>✧</span><div><strong>One screen. A universe of possibilities.</strong><p>Your progress stays on this device. Keep it safe with a backup.</p></div><div class="device-actions"><button class="btn secondary" id="homeControllers">PLAY WITH A CONTROLLER 🎮</button><button class="btn ghost" id="touchTest">TEST YOUR TOUCHSCREEN ↗</button></div></div>`;
$('#quickPlay').onclick=()=>{const picks=GAMES.filter(g=>!['funny','monster','air'].includes(g.id));setupGame(picks[Math.floor(Math.random()*picks.length)].id);};$('#worldSearch').oninput=e=>{worldQuery=e.target.value;deck();};$('#heroPlayers').onclick=choosePlayer;$('#addProfile').onclick=()=>profileEditor();$('#touchTest').onclick=touchTest;$('#homeControllers').onclick=()=>modal(controllerHelp(),d=>{d.querySelector('[data-controller-close]').onclick=()=>d.close();});document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>{DB.active=b.dataset.player;save();lobby();});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});deck();});deck();}
function deck(){let available=matchingWorlds(GAMES,filter,worldQuery);$('#worldCount').textContent=`${available.length} ${available.length===1?'world':'worlds'} to explore${worldQuery.trim()?' for “'+worldQuery.trim()+'”':''}.`;$('#deck').innerHTML=available.map((g,i)=>{let best=player()?.results.filter(r=>r.game===g.id&&r.difficulty===3&&!r.learn&&r.mode==='solo'&&(!['bugs','balloons','cafe','keeper','dig','battle'].includes(g.id)||r.ruleset==='refinement-v1'&&r.levelId===({bugs:'classic-1',balloons:'classic-1',cafe:'plate-1',keeper:'keeper-1',dig:'expedition-1',battle:'mixed-3'}[g.id]))).reduce((a,r)=>Math.max(a,r.score),0)||0;return `<button class="game-tile ${g.id==='paint'||g.id==='beat'?'creative-tile':''}" data-game="${g.id}" style="--accent:${COLORS[GAMES.indexOf(g)%COLORS.length]};--tile-index:${i}"><div class="tile-top"><span>WORLD ${String(GAMES.indexOf(g)+1).padStart(2,'0')}</span><span>${g.id==='battle'?'VS MODE':g.learn?'PLAY + LEARN':g.type==='creative'?'CREATE':'SKILL GAME'}</span></div><div class="tile-art">${artwork(g.id)}</div><div class="tile-copy"><div><h3>${g.name}</h3><p>${g.desc}</p></div><span class="tile-play">↗</span></div><div class="tile-meta"><span>${g.id==='beat'?'MUSIC STUDIO':g.tag.toUpperCase()}</span><span>${best?'★ '+best+' · HARD':g.id==='paint'?'MAKE YOUR MARK':g.id==='beat'?'DROP A BEAT':'READY WHEN YOU ARE'}</span></div></button>`;}).join('')||'<div class="world-empty"><h3>A different adventure awaits.</h3><p>Try another word or explore all the worlds.</p><button class="btn primary" id="clearWorldSearch">SHOW ALL WORLDS</button></div>';const clear=$('#clearWorldSearch');if(clear)clear.onclick=()=>{worldQuery='';filter='all';lobby();$('#worldSearch').focus();};}
function beatArt(){return `<svg viewBox="0 0 290 160" aria-hidden="true"><g transform="translate(52 21) rotate(-8 93 60)"><rect width="190" height="124" rx="15" fill="#22203b" stroke="#a889e7" stroke-width="3"/>${Array.from({length:12},(_,i)=>`<rect x="${15+(i%4)*41}" y="${13+Math.floor(i/4)*33}" width="30" height="24" rx="5" fill="${COLORS[i%6]}" opacity="${i%3?.85:.4}"/>`).join('')}</g><path d="M20 72v27m-8-19v11m249-31v34m-10-26v18m20-8v12" stroke="#46e2cf" stroke-width="4" stroke-linecap="round"/></svg>`;}
function choosePlayer(){modal(`<div class="eyebrow">CHOOSE YOUR EXPLORER</div><h2>Who’s playing?</h2><p>Your scores, creations, and trophies belong to you.</p><div class="profile-picker">${DB.profiles.map(p=>`<button class="profile-choice" data-pick="${p.id}" style="--player:${p.color}"><span class="avatar premium-avatar">${iconArt('avatar',p.avatar)}</span><strong>${esc(p.name)}</strong><small>LEVEL ${levelOf(p)}</small>${p.id===DB.active?'<span class="active-tag">PLAYING</span>':''}</button>`).join('')}<button class="profile-choice new" id="newPlayer"><span class="avatar">＋</span><strong>New player</strong></button></div>`,d=>{d.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{DB.active=b.dataset.pick;save();d.close();if(['home','players','boards','trophies','rivals','settings'].includes(route))navigate(route);});d.querySelector('#newPlayer').onclick=()=>profileEditor();});}
function profiles(){$('#view').innerHTML=heading('THE CREW','Meet your <em>all-stars.</em>','Every adventure starts with you. Pick a player, chase a record, make it yours.','<button class="btn primary" id="newProfile">＋ NEW PLAYER</button>')+`<div class="profile-grid">${DB.profiles.map(p=>{let pr=levelProgress(p),best=p.results.filter(r=>r.best!=null).sort((a,b)=>a.best-b.best)[0]?.best;return `<article class="profile-card bg-${esc(p.background)}" style="--player:${p.color}"><div class="profile-card-top"><span class="tag">LEVEL ${pr.level}</span><button class="icon-btn" data-edit="${p.id}" aria-label="Edit ${esc(p.name)}">✎</button></div><span class="avatar large ${p.cosmetic==='halo'?'halo':''}">${iconArt('avatar',p.avatar)}</span><h2>${esc(p.name)}</h2><div class="xp-track"><i style="width:${pr.value/pr.max*100}%"></i></div><p class="xp-label">${p.xp} XP · ${pr.max-pr.value} TO NEXT LEVEL</p><div class="profile-stats"><div><b>${p.points}</b><small>POINTS</small></div><div><b>${p.played}</b><small>GAMES</small></div><div><b>${p.won} / ${p.lost}</b><small>WINS / LOSSES</small></div><div><b>${p.longestStreak}</b><small>BEST STREAK</small></div><div><b>${best==null?'—':Math.round(best)+' ms'}</b><small>FASTEST REACTION</small></div><div><b>${p.achievements.filter(a=>!BADGES.find(b=>b.id===a.id)?.hidden).length}</b><small>ACHIEVEMENTS</small></div></div><div class="badge-strip">${p.achievements.filter(a=>!BADGES.find(b=>b.id===a.id)?.hidden).slice(0,7).map(a=>`<span title="${esc(BADGES.find(b=>b.id===a.id)?.name)}">${BADGES.find(b=>b.id===a.id)?.icon||'⭐'}</span>`).join('')||'<small>Your first trophy is waiting.</small>'}</div><button class="btn ${p.id===DB.active?'secondary':'primary'}" data-use="${p.id}">${p.id===DB.active?'✓ CURRENT PLAYER':'PLAY AS '+esc(p.name.toUpperCase())}</button></article>`;}).join('')}</div>`;$('#newProfile').onclick=()=>profileEditor();document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>profileEditor(b.dataset.edit));document.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>{DB.active=b.dataset.use;save();profiles();});}
function profileEditor(id){let p=id?player(id):null,selectedAvatar=p?.avatar||AVATARS[0],selectedColor=p?.color||COLORS[0];modal(`<div class="eyebrow">PLAYER CUSTOMIZATION</div><h2>${p?'Make it yours.':'Hello, new explorer.'}</h2><form id="profileForm"><label>Player name<input id="playerName" maxlength="24" required placeholder="Your name" value="${esc(p?.name||'')}" autocomplete="off"></label><button type="button" class="text-link" id="showKeyboard">⌨ On-screen keyboard</button><div id="nameKeyboard" class="name-keyboard" hidden>${'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map(k=>`<button type="button" data-key="${k}">${k}</button>`).join('')}<button type="button" data-key=" ">Space</button><button type="button" data-key="back">⌫</button></div><label>Choose your avatar</label><div class="avatar-options">${AVATARS.map(a=>`<button type="button" data-avatar="${a}" class="${a===selectedAvatar?'selected':''}">${a}</button>`).join('')}</div><label>Your color</label><div class="color-options">${COLORS.map(c=>`<button type="button" data-color="${c}" aria-label="Color ${c}" class="${c===selectedColor?'selected':''}" style="--swatch:${c}"></button>`).join('')}</div><div class="form-columns"><label>Avatar style<select id="cosmetic"><option value="none">Classic</option><option value="halo" ${levelOf(p)<3?'disabled':''} ${p?.cosmetic==='halo'?'selected':''}>Neon halo · Level 3</option></select></label><label>Profile background<select id="profileBg"><option value="orbit">Orbit</option><option value="stars" ${levelOf(p)<2?'disabled':''} ${p?.background==='stars'?'selected':''}>Starlight · Level 2</option><option value="aurora" ${levelOf(p)<5?'disabled':''} ${p?.background==='aurora'?'selected':''}>Aurora · Level 5</option></select></label><label>Arcade theme<select id="arcadeTheme"><option value="neon">Neon Universe</option><option value="aurora" ${levelOf(p)<4?'disabled':''} ${p?.theme==='aurora'?'selected':''}>Aurora · Level 4</option><option value="nebula" ${levelOf(p)<7?'disabled':''} ${p?.theme==='nebula'?'selected':''}>Pink Nebula · Level 7</option></select></label></div><div class="modal-actions">${p?'<button type="button" class="btn danger" id="deleteProfile">Delete profile</button>':''}<button type="submit" class="btn primary">${p?'SAVE CHANGES':'LET’S GO →'}</button></div><p class="form-error" id="profileError" role="alert"></p></form>`,d=>{d.querySelectorAll('[data-avatar]').forEach(b=>b.onclick=()=>{selectedAvatar=b.dataset.avatar;d.querySelectorAll('[data-avatar]').forEach(x=>x.classList.toggle('selected',x===b));});d.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{selectedColor=b.dataset.color;d.querySelectorAll('[data-color]').forEach(x=>x.classList.toggle('selected',x===b));});$('#showKeyboard').onclick=()=>$('#nameKeyboard').hidden=!$('#nameKeyboard').hidden;d.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{let n=$('#playerName');n.value=b.dataset.key==='back'?n.value.slice(0,-1):(n.value+b.dataset.key).slice(0,24);});$('#profileForm').onsubmit=e=>{e.preventDefault();let name=$('#playerName').value.trim();if(!name){$('#profileError').textContent='Please give your player a name.';return;}if(p){Object.assign(p,{name,avatar:selectedAvatar,color:selectedColor,cosmetic:$('#cosmetic').value,background:$('#profileBg').value,theme:$('#arcadeTheme').value});}else{p=newProfile(name,selectedAvatar,selectedColor);DB.profiles.push(p);DB.active=p.id;}save();d.close();navigate(route);};if(p)$('#deleteProfile').onclick=async()=>{if(DB.profiles.length<2){notify('Keep at least one player in your arcade.');return;}if(await ask('Delete '+p.name+'?', 'Their scores, achievements, and rivalry records will be removed. Saved artwork and music remain in device storage until you delete them separately.')){DB.profiles=DB.profiles.filter(x=>x.id!==p.id);DB.rivalries=DB.rivalries.filter(r=>!r.ids.includes(p.id));if(DB.active===p.id)DB.active=DB.profiles[0].id;save();d.close();navigate(route);}};});}
export function setupGame(id){if(updates.beforeGame(id,()=>setupGame(id)))return;selectGameSession(id);if(id!=='face')rememberWorld(id);if(id==='limit'){startLimitBreak();return;}if(id==='gladiator'||id==='math'){startQuest(id);return;}if(id==='spelling'){startSpelling();return;}if(id==='air'){startAir();return;}if(!player()){choosePlayer();return;}if(['funny','monster','zoo'].includes(id)){startMedia(id);return;}if(PREMIUM[id]){startPremium(id);return;}if(id==='gravity'){startGravity();return;}if(id==='dig')return;if(['slime','dentist','ninja'].includes(id)){startTouch(id);return;}if(id==='circuit'){startNew('circuit');return;}if(id==='face'){startNew('face');return;}if(id==='keeper')return;if(id==='paint'){startStudio();return;}if(id==='beat'){startBeat();return;}if(id==='build'){startSmash();return;}if(['bugs','balloons','cafe','keeper','battle'].includes(id)){startRefined(id);return;}let g=GAMES.find(g=>g.id===id),difficulty=3,mode='solo',learn=false,practice=false;const paint=()=>{modal(`<div class="game-intro" style="--accent:${COLORS[GAMES.indexOf(g)%8]}"><div class="intro-art">${artwork(g.id)}</div><div class="eyebrow">WORLD ${String(GAMES.indexOf(g)+1).padStart(2,'0')} · SKILL & ADVENTURE</div><h2>${g.name}</h2><p>${g.intro}</p><div class="mode-toggle"><button data-mode="solo" class="${mode==='solo'?'selected':''}">☺ 1 Player</button><button data-mode="versus" class="${mode==='versus'?'selected':''}">⚔ 2 Players</button></div><div class="form-columns"><label>Player 1<select id="p1">${DB.profiles.map(p=>`<option value="${p.id}" ${p.id===DB.active?'selected':''}>${p.avatar} ${esc(p.name)}</option>`).join('')}</select></label>${mode==='versus'?`<label>Player 2<select id="p2">${DB.profiles.filter(p=>p.id!==DB.active).map(p=>`<option value="${p.id}">${p.avatar} ${esc(p.name)}</option>`).join('')}</select></label>`:''}</div><label class="slider-label">CHALLENGE LEVEL <b id="difficultyName">${difficulty} · ${LEVELS[difficulty-1]}</b><input type="range" min="1" max="5" step="1" value="${difficulty}" id="difficulty" aria-label="Difficulty"><span class="range-labels"><span>EASY</span><span>HARD</span><span>EXPERT</span></span></label><p class="difficulty-note" id="difficultyNote"></p>${g.learn?`<label class="check-label"><input type="checkbox" id="learn" ${learn?'checked':''}><span>✦ Learning challenges <small>Separate records for learning and arcade modes.</small></span></label>`:''}${g.id==='build'&&mode==='solo'?`<label class="check-label"><input type="checkbox" id="practice" ${practice?'checked':''}><span>Free build <small>No timer or competitive score. Experiment and create.</small></span></label>`:''}<div class="intro-fairness">${mode==='versus'?(g.id==='cafe'||g.id==='build'?'↻ Alternating turns · identical seeded challenges':'✋ Simultaneous play · separate touch zones'):'60-second challenge · records saved when the round ends'}</div><button class="btn primary full" id="launch">${mode==='versus'?'ENTER THE ARENA ⚔':'LET’S PLAY →'}</button><button class="text-link" id="introRecords">View this game’s leaderboard ↗</button></div>`,d=>{d.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;paint();});$('#difficulty').oninput=e=>{difficulty=+e.target.value;$('#difficultyName').textContent=difficulty+' · '+LEVELS[difficulty-1];difficultyNote();};const difficultyNote=()=>{$('#difficultyNote').textContent=['Big targets, generous windows. Find your feet.','Quicker targets and a little less help.','Fast targets, precise touches, and rising pressure.','Short windows, distractions, and more at once.','Tiny targets, rapid patterns. A serious reflex challenge.'][difficulty-1];};difficultyNote();if($('#learn'))$('#learn').onchange=e=>learn=e.target.checked;if($('#practice'))$('#practice').onchange=e=>practice=e.target.checked;$('#introRecords').onclick=()=>{d.close();boardGame=id;boardDiff=difficulty;boardLearn=learn;boardMode=mode; navigate('boards');};$('#p1').onchange=()=>{const second=$('#p2');if(second){const previous=second.value;second.innerHTML=DB.profiles.filter(p=>p.id!==$('#p1').value).map(p=>`<option value="${p.id}" ${p.id===previous?'selected':''}>${p.avatar} ${esc(p.name)}</option>`).join('');}};$('#launch').onclick=()=>{let ids=[$('#p1').value];if(mode==='versus'){if(!$('#p2')?.value||$('#p2').value===ids[0]){notify('Choose two different players for a match.');return;}ids.push($('#p2').value);}DB.active=ids[0];save();d.close();cleanup?.();route='game';setImmersive(true);$('#view').className='view game-view';cleanup=launchGame($('#view'),{game:id,difficulty,learn,mode,ids,practice,exit:()=>navigate('home'),again:()=>setupGame(id),notify,ask});};});};paint();}
function startLimitBreak(initialPage='setup'){if(updates.beforeGame('limit',()=>startLimitBreak(initialPage)))return;selectGameSession('limit');cleanup?.();route='game';setImmersive(true);$('#view').className='view new-arcade-view';cleanup=openLimitBreak($('#view'),{initialPage,exit:()=>navigate('home'),notify,ask});window.scrollTo(0,0);}
function startQuest(game,initialPage='setup'){if(updates.beforeGame(game,()=>startQuest(game,initialPage)))return;selectGameSession(game);cleanup?.();route='game';setImmersive(true);$('#view').className='view new-arcade-view';cleanup=(game==='math'?openMathQuest:openGladiator)($('#view'),{initialPage,exit:()=>navigate('home'),notify,ask});window.scrollTo(0,0);}
function startSpelling(initialPage='setup'){if(updates.beforeGame('spelling',()=>startSpelling(initialPage)))return;selectGameSession('spelling');cleanup?.();route='game';setImmersive(true);$('#view').className='view new-arcade-view';cleanup=openSpelling($('#view'),{initialPage,exit:()=>navigate('home'),notify,ask});window.scrollTo(0,0);}
function startAir(initialPage='setup'){if(updates.beforeGame('air',()=>startAir(initialPage)))return;selectGameSession('air');cleanup?.();route='game';setImmersive(true);$('#view').className='view new-arcade-view';cleanup=openAirSlice($('#view'),{initialPage,exit:()=>navigate('home'),notify,ask});window.scrollTo(0,0);}
