function startPremium(game,initialPage='setup'){if(updates.beforeGame(game,()=>startPremium(game,initialPage)))return;selectGameSession(game);cleanup?.();route='game';setImmersive(true);$('#view').className='view new-arcade-view';cleanup=(game==='wars'?openWars3D:openPremium)($('#view'),{game,initialPage,exit:()=>navigate('home'),notify,ask,modal,classic:()=>startClassicWars()});window.scrollTo(0,0);}
function startClassicWars(){cleanup?.();route='game';setImmersive(true);$('#view').className='view new-arcade-view';cleanup=openPremium($('#view'),{game:'wars',exit:()=>navigate('home'),notify,ask,modal});window.scrollTo(0,0);}
function startGravity(initialPage='setup'){if(updates.beforeGame('gravity',()=>startGravity(initialPage)))return;selectGameSession('gravity');cleanup?.();route='game';setImmersive(true);$('#view').className='view new-arcade-view';cleanup=openGravity($('#view'),{initialPage,exit:()=>navigate('home'),notify,ask});window.scrollTo(0,0);}
function startTouch(game,initialPage='setup'){if(updates.beforeGame(game,()=>startTouch(game,initialPage)))return;selectGameSession(game);cleanup?.();route='game';setImmersive(true);$('#view').className='view new-arcade-view';cleanup=openTouchWorld($('#view'),{game,initialPage,exit:()=>navigate('home'),notify,ask});window.scrollTo(0,0);}
function startNew(kind,initialPage='setup'){if(updates.beforeGame(kind,()=>startNew(kind,initialPage)))return;selectGameSession(kind);cleanup?.();route='game';setImmersive(true);$('#view').className='view new-arcade-view';cleanup=openNewArcade($('#view'),{kind,initialPage,exit:()=>navigate('home'),notify,ask});window.scrollTo(0,0);}
function startRefined(game,initialPage='setup'){if(updates.beforeGame(game,()=>startRefined(game,initialPage)))return;selectGameSession(game);cleanup?.();route='game';setImmersive(true);$('#view').className='view refined-view';cleanup=openRefined($('#view'),{game,initialPage,exit:()=>navigate('home'),notify,ask});window.scrollTo(0,0);}
function startStudio(){creativeEntry('paint');}
function startSmash(initialPage='levels'){if(updates.beforeGame('build',()=>startSmash(initialPage)))return;selectGameSession('build');cleanup?.();route='smash';setImmersive(true);$('#view').className='view smash-view';cleanup=openSmash($('#view'),{exit:()=>navigate('home'),notify,ask,modal,initialPage});}
function startBeat(){creativeEntry('beat');}
function creativeEntry(game){if(updates.beforeGame(game,()=>creativeEntry(game)))return;selectGameSession(game);cleanup?.();route=game==='paint'?'studio':'beat';setImmersive(true);const host=$('#view');host.className='view '+(game==='paint'?'studio-view':'beat-view');const gate=createInstructionGate({game,onBack:()=>navigate('home'),onReview:()=>{if(game==='beat')document.querySelector('#beatPause')?.click();}});host.innerHTML=`<section class="creative-launch"><div class="creative-launch-art">${coverArt(game)}</div><div><span class="eyebrow">NEON ARCADE UNIVERSE · CREATE</span><h1>${game==='paint'?'Creative Studio':'Beat Lab'}</h1><p>${game==='paint'?'Paint, add stickers and photos, or create together on one shared canvas.':'Play instruments, build patterns and record your own music.'}</p><label>Player<select id="creativePlayer">${DB.profiles.map(p=>`<option value="${p.id}" ${p.id===DB.active?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><button class="btn primary" id="creativePlay">PLAY →</button><button class="btn secondary" id="creativeBack">← ARCADE</button></div></section>`;cleanup=()=>gate.dispose();$('#creativeBack').onclick=()=>navigate('home');$('#creativePlay').onclick=()=>{const id=$('#creativePlayer').value;DB.active=id;save();gate.show({players:[player(id).name]},()=>{const workspaceCleanup=(game==='paint'?openStudio:openBeatLab)(host,{exit:()=>navigate('home'),notify,ask,modal});cleanup=()=>{gate.dispose();workspaceCleanup?.();};});};}
function boards(){if(boardGame==='limit'){startLimitBreak('records');return;}if(boardGame==='math'||boardGame==='gladiator'){startQuest(boardGame,'records');return;}if(boardGame==='spelling'){startSpelling('records');return;}if(boardGame==='air'){startAir('records');return;}const rows=leaderboard(boardGame,boardDiff,boardLearn,boardMode,boardPeriod,personal);let all=DB.profiles.filter(p=>p.points>0).sort((a,b)=>b.points-a.points),fast=DB.profiles.flatMap(p=>p.results.filter(r=>r.best!=null&&r.hits>=5).map(r=>({p,r}))).sort((a,b)=>a.r.best-b.r.best)[0];const leader=(key)=>[...DB.profiles].filter(p=>p[key]>0).sort((a,b)=>b[key]-a[key])[0];let trophies=DB.profiles.filter(p=>p.achievements.length).sort((a,b)=>b.achievements.length-a.achievements.length)[0];$('#view').innerHTML=heading('HALL OF FAME','Earn your <em>legend.</em>','Real players. Real records. Every record is separated by challenge level and mode.')+`<div class="champion-strip"><div><span>♛</span><small>ARCADE CHAMPION</small><strong>${all[0]?all[0].avatar+' '+esc(all[0].name):'Your name here'}</strong><b>${all[0]?all[0].points+' points':'Play to claim the crown'}</b></div><div><small>MOST WINS</small><strong>${leader('won')?esc(leader('won').name)+' · '+leader('won').won:'—'}</strong></div><div><small>FASTEST REFLEX</small><strong>${fast?esc(fast.p.name)+' · '+Math.round(fast.r.best)+' ms':'—'}</strong><small>AT LEAST 5 VALID RESPONSES</small></div><div><small>LONGEST STREAK</small><strong>${leader('longestStreak')?esc(leader('longestStreak').name)+' · '+leader('longestStreak').longestStreak:'—'}</strong></div><div><small>HEAD-TO-HEAD WINS</small><strong>${leader('h2hWins')?esc(leader('h2hWins').name)+' · '+leader('h2hWins').h2hWins:'—'}</strong></div><div><small>MOST ACHIEVEMENTS</small><strong>${trophies?esc(trophies.name)+' · '+trophies.achievements.length:'—'}</strong></div></div><div class="board-controls panel"><label>World<select id="boardGame">${GAMES.filter(g=>!['paint','beat'].includes(g.id)).map(g=>`<option value="${g.id}" ${g.id===boardGame?'selected':''}>${g.name}</option>`).join('')}</select></label><label>Difficulty<select id="boardDiff">${LEVELS.map((l,i)=>`<option value="${i+1}" ${i+1===boardDiff?'selected':''}>${l}</option>`).join('')}</select></label><label>Challenge<select id="boardLearn"><option value="play" ${!boardLearn?'selected':''}>Arcade</option><option value="learn" ${boardLearn?'selected':''}>Learning</option></select></label><label>Players<select id="boardMode"><option value="solo" ${boardMode==='solo'?'selected':''}>Solo</option><option value="versus" ${boardMode==='versus'?'selected':''}>2-player</option></select></label><label>Records<select id="boardPeriod"><option value="all" ${boardPeriod==='all'?'selected':''}>All-time</option><option value="daily" ${boardPeriod==='daily'?'selected':''}>Today · device time</option><option value="personal" ${personal?'selected':''}>My personal bests</option></select></label></div>${rows.length?`<div class="podium">${[1,0,2].filter(i=>rows[i]).map(i=>{let r=rows[i];return `<div class="podium-player rank-${i+1}"><span class="avatar" style="--player:${r.profile.color}">${r.profile.avatar}</span><strong>${esc(r.profile.name)}</strong><span>${r.result.score} POINTS</span><div class="podium-block"><b>${['♛','Ⅱ','Ⅲ'][i]}</b><span>${['GOLD','SILVER','BRONZE'][i]}</span></div></div>`;}).join('')}</div><div class="table-wrap"><table><thead><tr><th>RANK</th><th>PLAYER</th><th>SCORE</th><th>DIFFICULTY</th><th>BEST / AVG REACTION</th><th>ACCURACY</th><th>RECORD DATE</th></tr></thead><tbody>${rows.map(({profile:p,result:r},i)=>`<tr><td><span class="rank-number">${i+1}</span></td><td>${p.avatar} ${esc(p.name)}</td><td class="score-cell">${r.score}</td><td>${LEVELS[r.difficulty-1]}</td><td>${r.best==null?'—':Math.round(r.best)+' / '+Math.round(r.avg)+' ms'}</td><td>${r.accuracy==null?'—':r.accuracy+'%'}</td><td>${new Date(r.at).toLocaleDateString()}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><span>✧</span><h2>A fresh leaderboard.</h2><p>Complete a round in this mode to make your mark.<br>Creative activities earn achievements instead of competitive scores.</p><button class="btn primary" id="boardPlay">PLAY THIS WORLD →</button></div>'}`;if(['bugs','balloons','cafe','keeper','battle'].includes(boardGame)){const jump=document.createElement('button');jump.className='btn accent';jump.textContent='NEW SKILL UPDATE RECORDS →';jump.onclick=()=>startRefined(boardGame,'records');$('#view').prepend(jump);}if(['funny','monster','zoo'].includes(boardGame)){const jump=document.createElement('button');jump.className='btn accent';jump.textContent='MEDIA CHALLENGE RECORDS →';jump.onclick=()=>startMedia(boardGame,'records');$('#view').prepend(jump);}if(PREMIUM[boardGame]){const jump=document.createElement('button');jump.className='btn accent';jump.textContent='CHALLENGE RECORDS →';jump.onclick=()=>startPremium(boardGame,'records');$('#view').prepend(jump);}if(boardGame==='gravity'){const jump=document.createElement('button');jump.className='btn accent';jump.textContent='GRAVITY LEVEL RECORDS →';jump.onclick=()=>startGravity('records');$('#view').prepend(jump);}if(['slime','dentist','ninja'].includes(boardGame)){const jump=document.createElement('button');jump.className='btn accent';jump.textContent='LEVEL RECORDS →';jump.onclick=()=>startTouch(boardGame,'records');$('#view').prepend(jump);}if(boardGame==='circuit'){const jump=document.createElement('button');jump.className='btn accent';jump.textContent='CIRCUIT LEVEL RECORDS →';jump.onclick=()=>startNew('circuit','records');$('#view').prepend(jump);}if(boardGame==='build'){const jump=document.createElement('button');jump.className='btn accent';jump.textContent='NEW DEMOLITION CAMPAIGN RECORDS →';jump.onclick=()=>startSmash('records');$('#view').prepend(jump);}$('#boardGame').onchange=e=>{boardGame=e.target.value;boards();};$('#boardDiff').onchange=e=>{boardDiff=+e.target.value;boards();};$('#boardLearn').onchange=e=>{boardLearn=e.target.value==='learn';boards();};$('#boardMode').onchange=e=>{boardMode=e.target.value;boards();};$('#boardPeriod').onchange=e=>{personal=e.target.value==='personal';boardPeriod=personal?'all':e.target.value;boards();};if($('#boardPlay'))$('#boardPlay').onclick=()=>setupGame(boardGame);}
function trophies(){let p=player(),pr=levelProgress(p);$('#view').innerHTML=heading('TROPHY ROOM',`${esc(p.name)}’s <em>constellation.</em>`,'Every badge has a story. Every story starts by playing.','<button class="btn secondary" id="trophySwitch">SWITCH PLAYER</button>')+`<div class="progress-panel panel"><span class="avatar large" style="--player:${p.color}">${iconArt('avatar',p.avatar)}</span><div><span class="eyebrow">LEVEL ${pr.level} EXPLORER</span><h2>${p.xp} <small>experience points</small></h2><div class="xp-track"><i style="width:${pr.value/pr.max*100}%"></i></div><p>${pr.max-pr.value} XP to the next level. Meaningful play, real progress.</p></div><strong>${p.achievements.filter(a=>!BADGES.find(b=>b.id===a.id)?.hidden).length}<small>OF ${BADGES.filter(b=>!b.hidden).length}<br>BADGES UNLOCKED</small></strong></div><div class="trophy-grid">${BADGES.filter(b=>!b.hidden).map((b,i)=>{let a=p.achievements.find(a=>a.id===b.id);return `<article class="trophy-card ${a?'unlocked':'locked'}"><span class="trophy-art" style="--badge-hue:${i*31}">${iconArt('trophy',b.id)}<i>✦</i></span><small>${a?'UNLOCKED '+new Date(a.at).toLocaleDateString():'YOUR NEXT ADVENTURE'}</small><h3>${b.name}</h3><p>${b.desc}</p><span class="tag">+${b.xp} XP ${a?'✓':'♧'}</span></article>`;}).join('')}</div><section class="panel unlocks"><h2>Make your universe yours.</h2><div><span>✦</span><p><strong>Level 2 · Starlight background</strong><br>${pr.level>=2?'Unlocked! Select it in your profile.':'Keep exploring to unlock.'}</p></div><div><span>◉</span><p><strong>Level 3 · Neon avatar halo</strong><br>${pr.level>=3?'Unlocked! Select it in your profile.':'A little glow for your next big adventure.'}</p></div><div><span>🌌</span><p><strong>Level 5 · Aurora profile background</strong><br>${pr.level>=5?'Unlocked! Select it in your profile.':'Paint your profile with the northern lights.'}</p></div></section>`;$('#trophySwitch').onclick=choosePlayer;}
function rivals(){$('#view').innerHTML=heading('FRIENDLY RIVALRIES','Same screen.<br><em>Big competition.</em>','Completed matches count. Rematches encouraged. High fives required.')+`<div class="rivalry-grid">${DB.rivalries.filter(r=>r.ids.every(id=>player(id))).map(r=>{let[a,b]=r.ids.map(id=>player(id));return `<article class="rivalry-card panel"><div class="rival-faces"><span class="avatar" style="--player:${a.color}">${a.avatar}</span><b>VS</b><span class="avatar" style="--player:${b.color}">${b.avatar}</span></div><h3>${esc(a.name)} <em>&</em> ${esc(b.name)}</h3><div class="rival-score"><strong>${r.wins[a.id]||0}</strong><span>${r.matches} MATCHES<br>${r.draws} DRAWS</span><strong>${r.wins[b.id]||0}</strong></div><p>${(r.wins[a.id]||0)===(r.wins[b.id]||0)?'Neck and neck. Time for a rematch!':esc((r.wins[a.id]||0)>(r.wins[b.id]||0)?a.name:b.name)+' leads the rivalry.'}</p></article>`;}).join('')||'<div class="empty-state"><span>⚔</span><h2>Find your friendly rival.</h2><p>Play a two-player game to start your story.</p><button class="btn primary" data-game="battle">START A TAP BATTLE →</button></div>'}</div>`;}
function settings(){$('#view').innerHTML=heading('MISSION CONTROL','Your arcade.<br><em>Your way.</em>','Fine-tune the sound, check your display, and keep your family’s progress safe.')+`<div class="settings-grid"><section class="panel"><h2>Sound & atmosphere</h2><label class="slider-label">Sound effects <output id="sfxVal">${DB.settings.sound}%</output><input id="sfxVolume" type="range" min="0" max="100" value="${DB.settings.sound}"></label><label class="slider-label">Background music <output id="musicVal">${DB.settings.music}%</output><input id="musicVolume" type="range" min="0" max="100" value="${DB.settings.music}"></label><label class="check-label"><input id="musicOn" type="checkbox" ${DB.settings.musicOn?'checked':''}>Play gentle lobby music</label><label class="check-label"><input id="muted" type="checkbox" ${DB.settings.muted?'checked':''}>Mute all audio, including Beat Lab</label><p class="muted">Beat Lab pauses background music while you create.</p><label class="check-label"><input id="motion" type="checkbox" ${DB.settings.reduceMotion?'checked':''}>Reduce motion & effects</label></section><section class="panel"><h2>Your display</h2><p>Use the app fullscreen for the biggest play space. All games also support a mouse.</p><button class="btn primary" id="fullSettings">⛶ FULLSCREEN</button><button class="btn secondary" id="settingsTouch">✋ TOUCH TEST</button><button class="btn secondary" id="settingsControllers">🎮 CONTROLLER GUIDE</button><h3>Offline play</h3><p id="cacheStatus">Checking offline resources…</p><button class="btn secondary" id="checkAppUpdate">CHECK FOR UPDATES</button><p id="appUpdateStatus" role="status"></p><p class="muted">Offline play uses this browser’s saved resources. Open the arcade online to download updates. Use Install Update in the lobby when ready. Close other arcade tabs first. Updates never clear player progress. Private sign-in may still require a connection on a new browser.</p></section><section class="panel"><h2>Backup & restore</h2><p>Your profiles, records, drawings, music, photos, videos, monsters, zoo layouts and voices live on this device. Export a backup before clearing your browser or changing computers.</p><button class="btn primary" id="backup">↓ EXPORT EVERYTHING</button><label class="btn secondary file-btn">↑ RESTORE BACKUP<input id="restore" type="file" accept="application/json,.json" hidden></label><p id="backupStatus" role="status"></p><p class="muted">Restore replaces the current arcade data. Keep a backup of both devices first.</p></section><section class="panel"><h2>About this universe</h2><button class="btn secondary" id="updateHistory">✦ UPDATE HISTORY</button><button class="text-link" id="resetNotices">Reset update acknowledgments only</button><p class="muted">Update notes and acknowledgments work offline on this browser. Backups and profile changes do not reset them. Clearing site data removes them and your local progress; export a backup first. Read-aloud uses the browser’s voices and may need a connection for some voices.</p><p>Neon Arcade Universe · version ${APP_VERSION}<br>${GAMES.length} worlds. No ads. No external game API.</p><p>Profiles and leaderboards are local to this browser. Device owners can edit browser storage; these are friendly family competitions.</p><a class="text-link" href="vendor/THIRD_PARTY.txt" target="_blank" rel="noopener">Audio encoder & third-party credits ↗</a>${Object.keys(DB.legacy||{}).length?`<h3>Preserved original records</h3><p class="muted">These predate player profiles and difficulty rankings, so they remain unassigned.</p><div class="legacy-records">${Object.entries(DB.legacy).map(([id,n])=>`<span>${esc(GAMES.find(g=>g.id===id)?.name||id)}<b>${esc(n)}</b></span>`).join('')}</div>`:''}</section></div>`;
for(let[id,key,out]of[['sfxVolume','sound','sfxVal'],['musicVolume','music','musicVal']])$('#'+id).oninput=e=>{audio();DB.settings[key]=+e.target.value;$('#'+out).textContent=e.target.value+'%';save();applyAudio();};for(let[id,key]of[['musicOn','musicOn'],['muted','muted'],['motion','reduceMotion']])$('#'+id).onchange=e=>{audio();DB.settings[key]=e.target.checked;save();applyAudio();};$('#fullSettings').onclick=fullscreen;$('#settingsTouch').onclick=touchTest;$('#settingsControllers').onclick=()=>modal(controllerHelp(),d=>{d.querySelector('[data-controller-close]').onclick=()=>d.close();});$('#backup').onclick=async()=>{try{$('#backupStatus').textContent='Preparing your profiles and media…';await backup();$('#backupStatus').textContent='Backup downloaded. Keep it somewhere safe.';}catch(e){$('#backupStatus').textContent='Backup failed: '+e.message;}};$('#restore').onchange=async e=>{let f=e.target.files[0];e.target.value='';if(!f)return;if(!await ask('Restore this backup?','This replaces all current player progress and saved creations on this browser. Export a backup first if you want to keep them.'))return;try{$('#backupStatus').textContent='Restoring…';await restore(f);notify('Your arcade backup has been restored.');settings();}catch(e){$('#backupStatus').textContent='Could not restore: '+e.message;}};$('#updateHistory').onclick=()=>updates.showHistory();$('#resetNotices').onclick=async()=>{if(await ask('Show update notices again?','Reset only update acknowledgments on this browser. Profiles, scores, settings and saved creations stay unchanged.')){updates.store.reset();updates.arcade();}};$('#checkAppUpdate').onclick=()=>appUpdater?.check();offlineStatus();renderAppUpdate();}
async function offlineStatus(){let n=$('#cacheStatus');if(!n)return;try{let keys=await caches.keys();n.textContent=keys.some(k=>k.startsWith('lba-universe'))?'✓ Offline resources cached on this browser.':'Resources are still loading. Keep this page open online for a moment.';}catch{n.textContent='Offline caching isn’t available in this browser session.';}}
function touchTest(){let max=0,touches=new Map();modal(`<div class="eyebrow">DEVICE CHECK</div><h2>High five. Or ten.</h2><p>Put several fingers in the area together. Each dot should move independently.</p><div class="touch-pad" id="touchPad"><span>TOUCH HERE</span></div><div class="touch-count" id="touchCount">0 pointers · best 0</div><p class="muted">One dot only? Check the Windows touchscreen driver. A mouse normally reports one pointer.</p>`,d=>{let pad=d.querySelector('#touchPad');function count(){max=Math.max(max,touches.size);$('#touchCount').textContent=`${touches.size} pointers · best ${max}`;}function move(e){let n=touches.get(e.pointerId);if(!n)return;let r=pad.getBoundingClientRect();n.style.left=e.clientX-r.left+'px';n.style.top=e.clientY-r.top+'px';}pad.onpointerdown=e=>{e.preventDefault();pad.setPointerCapture(e.pointerId);let n=document.createElement('i');n.style.background=COLORS[touches.size%8];pad.append(n);touches.set(e.pointerId,n);move(e);count();};pad.onpointermove=move;for(let ev of ['pointerup','pointercancel','lostpointercapture'])pad.addEventListener(ev,e=>{touches.get(e.pointerId)?.remove();touches.delete(e.pointerId);count();});});}
const knownLevels=new Map(DB.profiles.map(p=>[p.id,levelOf(p)]));bus.addEventListener('change',()=>{for(let p of DB.profiles){let l=levelOf(p),old=knownLevels.get(p.id);if(old!=null&&l>old){notify('🌟 '+p.name+' reached Level '+l+'!','achievement');fx('win');}knownLevels.set(p.id,l);}});playerChip();navigate(location.hash.slice(1)||'home');updates.attachBadge();updates.arcade();$('#boot').classList.add('ready');setTimeout(()=>$('#boot').remove(),500);
function renderAppUpdate(){
 const state=appUpdater?.state;if(!state)return;
 let button=$('#appUpdateReady');if(!button){button=document.createElement('button');button.id='appUpdateReady';button.className='app-update-ready';button.textContent='↑ UPDATE READY · INSTALL & RELOAD';button.onclick=()=>appUpdater.apply();document.body.append(button);}
 button.hidden=!(state.ready&&['home','settings'].includes(route))||state.status==='applying';
 const text=$('#appUpdateStatus');if(text)text.textContent=state.message||({checking:'Checking for updates…',downloading:'Downloading the complete update. Keep the arcade open online.',ready:'Update ready. Finish playing, close other arcade tabs, then use Install Update.',current:'This browser has no downloaded update waiting. Online checks run when you return to the arcade.',applying:'Installing update…',unsupported:'Offline updates are unavailable in this browser.'}[state.status]||'');
 let install=$('#appInstallDialog');if(state.status==='applying'){if(!install){install=document.createElement('dialog');install.id='appInstallDialog';install.className='modal';install.innerHTML='<h2>Installing your update…</h2><p>The arcade will reload in a moment. Your profiles, scores and saved creations stay on this device.</p>';install.oncancel=e=>e.preventDefault();document.body.append(install);install.showModal();}}else if(install){install.close();install.remove();}
}
appUpdater=createAppUpdater({serviceWorker:navigator.serviceWorker,canApply:()=>['home','settings'].includes(route),onState:state=>{renderAppUpdate();if(state.message)notify(state.message);},reload:()=>location.reload()});
appUpdater.start();
let lastUpdateCheck=0;const checkOnlineUpdate=()=>{if(document.hidden||!navigator.onLine||Date.now()-lastUpdateCheck<60000)return;lastUpdateCheck=Date.now();appUpdater.check();};
window.addEventListener('online',checkOnlineUpdate);document.addEventListener('visibilitychange',checkOnlineUpdate);
window.addEventListener('online',()=>$('#connection').textContent='LOCAL PLAY · READY');window.addEventListener('offline',()=>$('#connection').textContent='OFFLINE · KEEP PLAYING');

const secretTaps=new SecretTaps();
for(const logo of document.querySelectorAll('.wordmark,.rail-logo')){
 logo.addEventListener('click',e=>{if(route==='home')e.preventDefault();});
 logo.addEventListener('pointerup',e=>{if(route!=='home'||!e.isPrimary)return;if(secretTaps.tap(performance.now())){secretTaps.reset();logo.classList.add('secret-shake');fx('secret');const reveal=document.createElement('div');reveal.className='secret-reveal';reveal.innerHTML='<span>✦</span><strong>A little secret…</strong>';document.body.append(reveal);setTimeout(()=>{logo.classList.remove('secret-shake');reveal.remove();if(route==='home')startNew('face');},650);}});
}
for(const type of ['dragstart','selectstart','contextmenu'])document.addEventListener(type,e=>{const target=e.target.nodeType===1?e.target:e.target.parentElement;if(!target?.closest('input,textarea,[contenteditable="true"]'))e.preventDefault();});

const arcadeController=createArcadeController();
window.addEventListener('pagehide',()=>arcadeController.pointers.cancelAll());
